def execute_transfer(sender, receiver, amount):
    """
    Wrapper that handles validation and observability around the core transfer logic.
    """
    validate_transfer(sender, amount)

    # record that we are attempting the transfer (pending by default)
    record_transfer_attempt(sender.account_id, receiver.account_id, amount)

    # Simulate a transient failure chance before mutating state to avoid partial updates
    if random.random() < 0.3:
        record_transfer_attempt(sender.account_id, receiver.account_id, amount, status="failed")
